.dropdown-menu, .context-menu, #toast-container > .toast, #preloader,
input, select, .text_pole, .menu_button, .extension_button {
    background-color: var(--bg-dark) !important;
}

/* 文字覆盖 */
body, .name_text, .mesIDDisplay, .mes_timer, .tokenCounterDisplay,
.toast-title, .toast-message, #send_textarea, .dropdown-menu li a {
    color: var(--text-main) !important;
}

/* 边框覆盖 */
.mes, #send_form, #send_textarea, input, select, .text_pole,
.menu_button, .dropdown-menu, .drawer-content {
    border-color: var(--border-dark) !important;
}

/* 次级背景 */
.mes_reasoning_content, .select2-container--default .select2-selection__choice {
    background-color: var(--bg-card) !important;
}

/* 文字颜色微调 */
.mes_timer, .tokenCounterDisplay, .timestamp {
    color: var(--text-muted) !important;
}

/* 占位符 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    color: var(--text-muted) !important;
}

/* 滑块轨道 */
input[type="range"] {
    background-color: var(--border-dark) !important;
